package com.ftk.tpip.control.application.integration;

import com.fasterxml.jackson.databind.*;import com.ftk.tpip.integration.domain.exception.PolicyCodeAlreadyExistsException;import com.ftk.tpip.integration.domain.model.*;import com.ftk.tpip.integration.domain.repository.*;import com.ftk.tpip.mapping.api.MappingDiagnostic;import com.ftk.tpip.policy.api.*;import com.ftk.tpip.policy.compiler.DefaultPolicyCompiler;import com.ftk.tpip.policy.ir.CompiledPolicyPlan;import com.ftk.tpip.shared.AssetCode;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class IntegrationPolicyApplicationService{private final IntegrationPolicyRepository policies;private final IntegrationBindingRepository bindings;private final PolicyTypeRepository types;private final PolicyContentCanonicalizer canonicalizer;private final PolicyCompiler compiler;private final ObjectMapper json;public IntegrationPolicyApplicationService(IntegrationPolicyRepository p,IntegrationBindingRepository b,PolicyTypeRepository t,PolicyContentCanonicalizer c,PolicyCompiler compiler,ObjectMapper json){this.policies=p;this.bindings=b;this.types=t;this.canonicalizer=c;this.compiler=compiler;this.json=json;}
@Transactional public IntegrationPolicy create(long bindingId,String code,String name,String actor){requireBinding(bindingId);AssetCode c=AssetCode.of(code);if(policies.findByCode(c).isPresent())throw new PolicyCodeAlreadyExistsException(c.value());return policies.create(IntegrationPolicy.create(bindingId,c,name),actor(actor));}@Transactional(readOnly=true)public IntegrationPolicy get(long id){return policies.findById(id).orElseThrow(()->new IntegrationPolicyNotFoundException(id));}@Transactional(readOnly=true)public IntegrationPolicyPage list(Long bindingId,String keyword,PolicyStatus status,int page,int size){if(page<0||size<1||size>200)throw new IllegalArgumentException("invalid pagination");long o=(long)page*size;if(o>Integer.MAX_VALUE)throw new IllegalArgumentException("page offset too large");var q=new IntegrationPolicyQuery(bindingId,keyword,status,(int)o,size);return new IntegrationPolicyPage(policies.findAll(q),page,size,policies.count(q));}@Transactional public IntegrationPolicy update(long id,String name,PolicyStatus status,long rowVersion,String actor){var p=get(id);if(status==PolicyStatus.ACTIVE)requireBinding(p.bindingId());return policies.update(p.revise(name,status,rowVersion),actor(actor));}
@Transactional public IntegrationPolicyVersion createVersion(long id,JsonNode document,String actor){var p=requireActive(id);requireBinding(p.bindingId());String normalized=canonicalizer.document(document);JsonNode node=read(normalized);compile(p,1,node);String checksum=canonicalizer.checksum(DefaultPolicyCompiler.DSL_API_VERSION+"|"+normalized);return policies.createVersion(IntegrationPolicyVersion.compiled(id,DefaultPolicyCompiler.DSL_API_VERSION,normalized,DefaultPolicyCompiler.COMPILER_VERSION,"[]",checksum),actor(actor));}
@Transactional(readOnly=true)public List<IntegrationPolicyVersion> versions(long id){get(id);return policies.findVersions(id);}@Transactional(readOnly=true)public IntegrationPolicyVersion version(long id,long versionId){get(id);return policies.findVersion(id,versionId).orElseThrow(()->new IntegrationPolicyVersionNotFoundException(id,versionId));}@Transactional(readOnly=true)public CompiledPolicyPlan plan(long id,long versionId){var p=get(id);var v=version(id,versionId);return compile(p,v.versionNo(),read(v.normalizedDocument()));}@Transactional public IntegrationPolicyVersion publish(long id,long versionId,String actor){var p=requireActive(id);requireBinding(p.bindingId());plan(id,versionId);return policies.publishVersion(id,versionId,actor(actor));}
@Transactional(readOnly=true)public CompiledPolicyPlan compileScoped(String policyCode,int version,JsonNode document){return compiler.compile(new PolicyDocument(AssetCode.of(policyCode),version,DefaultPolicyCompiler.DSL_API_VERSION,document),registry());}
private CompiledPolicyPlan compile(IntegrationPolicy p,int version,JsonNode node){return compiler.compile(new PolicyDocument(p.policyCode(),version,DefaultPolicyCompiler.DSL_API_VERSION,node),registry());}private PolicyTypeRegistrySnapshot registry(){return new PolicyTypeRegistrySnapshot(types.findAll(true).stream().map(this::descriptor).toList());}private PolicyTypeDescriptor descriptor(PolicyTypeDefinition d){return new PolicyTypeDescriptor(d.policyTypeCode(),d.semanticVersion(),d.allowedStages().stream().map(x->PolicyStage.valueOf(x.name())).collect(java.util.stream.Collectors.toSet()),read(d.configurationSchema()),d.runtimeCompatibility(),d.deterministic(),d.sideEffect(),d.securityClassification().name(),d.idempotencyRequirement()==null?null:d.idempotencyRequirement().name(),d.status()==PolicyTypeStatus.ACTIVE);}private JsonNode read(String v){try{return json.readTree(v);}catch(Exception e){throw new IllegalStateException("Stored policy JSON is invalid",e);}}private IntegrationPolicy requireActive(long id){var p=get(id);if(p.status()!=PolicyStatus.ACTIVE)throw new IllegalArgumentException("Policy must be ACTIVE");return p;}private void requireBinding(long id){var b=bindings.findById(id).orElseThrow(()->new IllegalArgumentException("bindingId does not exist: "+id));if(b.status()!=BindingStatus.ACTIVE)throw new IllegalArgumentException("bindingId must reference an ACTIVE binding");}private static String actor(String a){if(a==null||a.isBlank()||a.trim().length()>100)throw new IllegalArgumentException("X-Operator is blank or too long");return a.trim();}}
